import { Client } from "@modelcontextprotocol/client";
import { StdioClientTransport } from "@modelcontextprotocol/client/stdio";
import { createHash } from "node:crypto";
import { join } from "node:path";
const cwd=process.cwd();
const transport=new StdioClientTransport({command:process.execPath,args:[join(cwd,"bin","pc-browser-tab-mcp-stdio.js")],cwd,env:{...process.env,PC_CONTROL_ENABLE_BROWSER_TAB_CAPTURE:"1",PC_CONTROL_BROWSER_CDP_ALLOWED_PORTS:"17410,17447"},stderr:"pipe"});
const client=new Client({name:"local-browser-cdp-canary",version:"1.0.0"});
try {
 await client.connect(transport);
 const names=(await client.listTools()).tools.map(t=>t.name).sort();
 if(JSON.stringify(names)!==JSON.stringify(["browser.tab.capture","browser.tab.list"]))throw Error("unexpected_tools");
 const results=[];
 for(const port of [17410,17447]){
   const listing=await client.callTool({name:"browser.tab.list",arguments:{port}});
   if(listing.isError)throw Error("list_error");
   const tabs=JSON.parse(listing.content.find(x=>x.type==="text").text).tabs;
   const t=tabs.find(x=>new URL(x.url).hostname==="127.0.0.1");
   if(!t)throw Error("no_local_tab_"+port);
   const response=await client.callTool({name:"browser.tab.capture",arguments:{port,target_id:t.target_id,expected_url:t.url}});
   if(response.isError)throw Error("capture_error_"+port);
   const media=response.content.find(x=>x.type==="image");
   const metadata=JSON.parse(response.content.find(x=>x.type==="text").text);
   if(media?.mimeType!=="image/png")throw Error("no_png_media");
   const bytes=Buffer.from(media.data,"base64");
   const digest=createHash("sha256").update(bytes).digest("hex");
   if(digest!==metadata.sha256)throw Error("hash_mismatch");
   results.push({port,image:true,width:metadata.width,height:metadata.height,bytes:bytes.length,shaVerified:true,pixelsInText:response.content.find(x=>x.type==="text").text.includes(media.data)});
 }
 console.log(JSON.stringify({ok:true,tools:names,results}));
} catch(e) {console.log(JSON.stringify({ok:false,error:e.code||e.message||"unknown"}));process.exitCode=1;}
finally {await client.close().catch(()=>{});}
